import torch
from torch import nn

class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.layers = nn.Sequential(
            nn.Linear(4, 16),   # 4 inputs -> 16 hidden
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(16, 3),   # 3 classes (logits)
        )

    def forward(self, x):
        return self.layers(x)

model = Net()
print(model)
